# These modules are already injected into the sandbox runtime. Exact,
# conventional imports are accepted for model ergonomics, then removed before
# validation/execution. This does not enable Python's import machinery.
PRELOADED_IMPORT_ALIASES = {
    "pandas": {"pandas", "pd"},
    "json": {"json"},
    "ast": {"ast"},
    "math": {"math"},
    "re": {"re"},
}


class SandboxValidationError(ValueError):
    """Raised when submitted code violates the restricted execution policy."""


class _RedundantImportStripper(ast.NodeTransformer):
    """Remove narrowly whitelisted imports for modules already in globals."""

    def __init__(self) -> None:
        self.removed_imports: list[str] = []

    def visit_Import(self, node: ast.Import) -> ast.AST:
        rendered: list[str] = []

        for alias in node.names:
            allowed_aliases = PRELOADED_IMPORT_ALIASES.get(alias.name)
            if allowed_aliases is None:
                raise SandboxValidationError(
                    f"Import of '{alias.name}' is not allowed. "
                    "Use only modules already provided by the sandbox."
                )

            effective_name = alias.asname or alias.name
            if effective_name not in allowed_aliases:
                expected = ", ".join(sorted(allowed_aliases))
                raise SandboxValidationError(
                    f"Import alias '{effective_name}' is not allowed for '{alias.name}'. "
                    f"Use one of: {expected}."
                )

            rendered.append(
                f"{alias.name} as {alias.asname}" if alias.asname else alias.name
            )

        self.removed_imports.append("import " + ", ".join(rendered))
        return ast.copy_location(ast.Pass(), node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.AST:
        module = node.module or ""
        raise SandboxValidationError(
            f"From-imports are not allowed: from {module} import ..."
        )


class _ResultCaptureTransformer(ast.NodeTransformer):
    """Capture a final expression as `result` when no explicit result assignment exists."""

    @staticmethod
    def _assigns_result(node: ast.AST) -> bool:
        class Finder(ast.NodeVisitor):
            found = False

            def visit_Name(self, child: ast.Name) -> None:
                if child.id == "result" and isinstance(child.ctx, ast.Store):
                    self.found = True

            def visit_FunctionDef(self, child: ast.FunctionDef) -> None:
                return

            def visit_AsyncFunctionDef(self, child: ast.AsyncFunctionDef) -> None:
                return

            def visit_ClassDef(self, child: ast.ClassDef) -> None:
                return

            def visit_Lambda(self, child: ast.Lambda) -> None:
                return

        finder = Finder()
        finder.visit(node)
        return bool(finder.found)

    def visit_Module(self, node: ast.Module) -> ast.Module:
        self.generic_visit(node)
        if any(self._assigns_result(statement) for statement in node.body):
            return node
        if node.body and isinstance(node.body[-1], ast.Expr):
            final_expression = node.body[-1]
            node.body[-1] = ast.copy_location(
                ast.Assign(
                    targets=[ast.Name(id="result", ctx=ast.Store())],
                    value=final_expression.value,
                ),
                final_expression,
            )
        return node


class _SandboxValidator(ast.NodeVisitor):
    def _validate_identifier(self, name: str, *, storing: bool = False) -> None:
        if name != "_" and name.startswith("_"):
            raise SandboxValidationError(f"Identifiers beginning with '_' are not allowed: {name}")
        if name in BLOCKED_NAMES:
            raise SandboxValidationError(f"Use of '{name}' is not allowed.")
        if storing and name in PROTECTED_RUNTIME_NAMES:
            raise SandboxValidationError(f"The supplied runtime name '{name}' is read-only.")

    def visit(self, node: ast.AST):  # type: ignore[override]
        if isinstance(node, BLOCKED_NODES):
            raise SandboxValidationError(f"{type(node).__name__} statements are not allowed.")
        return super().visit(node)

    def visit_Name(self, node: ast.Name) -> None:
        self._validate_identifier(node.id, storing=isinstance(node.ctx, (ast.Store, ast.Del)))

    def visit_arg(self, node: ast.arg) -> None:
        self._validate_identifier(node.arg, storing=True)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        attribute = node.attr
        if attribute.startswith("_") or attribute in BLOCKED_ATTRIBUTES or attribute in BLOCKED_NAMES:
            raise SandboxValidationError(f"Attribute access is not allowed: {attribute}")
        if attribute.startswith("read_"):
            raise SandboxValidationError(f"External data-loading method is not allowed: {attribute}")
        self.generic_visit(node)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._validate_identifier(node.name, storing=True)
        if node.decorator_list:
            raise SandboxValidationError("Function decorators are not allowed.")
        self.generic_visit(node)


def _is_missing_scalar(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, (list, tuple, set, dict, pd.Series, pd.DataFrame)):
        return False
    try:
        missing = pd.isna(value)
    except Exception:
        return False
    return bool(missing) if isinstance(missing, (bool, int)) else False


def _parse_relationship(value: Any) -> list[str]:
    if _is_missing_scalar(value):
        return []
    if isinstance(value, (list, tuple, set)):
        raw_values = list(value)
    else:
        text = str(value).strip()
        if not text or text in {"[]", "null", "None", "nan", "NaN"}:
            return []
        try:
            parsed = json.loads(text)
        except Exception:
            try:
                parsed = ast.literal_eval(text)
            except Exception:
                parsed = None
        if isinstance(parsed, (list, tuple, set)):
            raw_values = list(parsed)
        elif isinstance(parsed, str):
            raw_values = [parsed]
        elif "," in text:
            raw_values = text.split(",")
        else:
            raw_values = [text]

    output: list[str] = []
    seen: set[str] = set()
    for item in raw_values:
        cleaned = str(item).strip().strip("'\"")
        if cleaned and cleaned not in seen:
            seen.add(cleaned)
            output.append(cleaned)
    return output


def _parse_ids(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, dict):
        value = value.get("ids", [])
    if isinstance(value, (list, tuple, set)):
        output: list[str] = []
        for item in value:
            output.extend(_parse_ids(item))
        return output

    text = str(value).strip()
    if not text:
        return []
    try:
        parsed = json.loads(text)
    except Exception:
        try:
            parsed = ast.literal_eval(text)
        except Exception:
            parsed = None
    if isinstance(parsed, (dict, list, tuple, set)):
        return _parse_ids(parsed)

    pieces: list[str] = []
    for line in text.splitlines():
        pieces.extend(line.split(","))
    return [piece.strip().strip("'\"") for piece in pieces if piece.strip().strip("'\"")]


def _json_ready(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, pd.DataFrame):
        return _records(value)
    if isinstance(value, pd.Series):
        return _json_ready(value.to_dict())
    if isinstance(value, dict):
        return {str(key): _json_ready(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_ready(item) for item in value]
    if isinstance(value, set):
        return [_json_ready(item) for item in sorted(value, key=str)]
    if _is_missing_scalar(value):
        return None
    if isinstance(value, (pd.Timestamp, pd.Timedelta)):
        return value.isoformat() if hasattr(value, "isoformat") else str(value)
    if hasattr(value, "item"):
        try:
            return value.item()
        except Exception:
            pass
    if isinstance(value, Path):
        return str(value)
    return value


def _records(
    frame: Any,
    parse_relationships: bool = True,
    fields: list[str] | tuple[str, ...] | None = None,
) -> list[dict[str, Any]]:
    if isinstance(frame, pd.Series):
        frame = frame.to_frame().T
    if not isinstance(frame, pd.DataFrame):
        converted = _json_ready(frame)
        return converted if isinstance(converted, list) else [converted]

    output = frame.copy()
    if fields is not None:
        selected = [field for field in fields if field in output.columns]
        output = output.loc[:, selected]
    if parse_relationships:
        for column in RELATIONSHIP_COLUMNS:
            if column in output.columns:
                output[column] = output[column].apply(_parse_relationship)
    return _json_ready(output.to_dict(orient="records"))


def _hydrate_ids(ids: Any, frame: pd.DataFrame, fields: list[str] | None = None) -> dict[str, Any]:
    wanted = list(dict.fromkeys(_parse_ids(ids)))
    if "id" not in frame.columns:
        return {
            "records": [],
            "missing_ids": wanted,
            "duplicate_dataset_ids": [],
            "error": "The dataframe does not contain an 'id' column.",
        }

    id_series = frame["id"].astype(str)
    matched = frame[id_series.isin(wanted)].copy()
    duplicate_ids = sorted(
        matched.loc[matched["id"].astype(str).duplicated(keep=False), "id"].astype(str).unique().tolist()
    )
    effective_fields = fields
    if fields is not None and "id" not in fields:
        effective_fields = ["id", *fields]
    matched_records = _records(matched, fields=effective_fields)
    by_id: dict[str, dict[str, Any]] = {}
    for record in matched_records:
        record_id = str(record.get("id", ""))
        if record_id and record_id not in by_id:
            by_id[record_id] = record

    return {
        "records": [by_id[item] for item in wanted if item in by_id],
        "missing_ids": [item for item in wanted if item not in by_id],
        "duplicate_dataset_ids": duplicate_ids,
    }


def _lookup_id(aml_id: Any, frame: pd.DataFrame, fields: list[str] | None = None) -> dict[str, Any]:
    wanted = _parse_ids(aml_id)
    if len(wanted) != 1:
        return {
            "record": None,
            "status": "invalid_request",
            "message": "lookup_id expects exactly one AML.ID.",
        }
    hydrated = _hydrate_ids(wanted, frame, fields=fields)
    return {
        "record": hydrated["records"][0] if hydrated["records"] else None,
        "status": "success" if hydrated["records"] else "no_match",
        "missing_ids": hydrated["missing_ids"],
        "duplicate_dataset_ids": hydrated["duplicate_dataset_ids"],
    }


def _relationship_ids(aml_id: Any, column: str, frame: pd.DataFrame) -> dict[str, Any]:
    if column not in RELATIONSHIP_COLUMNS:
        return {
            "source_id": str(aml_id),
            "column": column,
            "ids": [],
            "status": "invalid_column",
            "message": f"Unsupported relationship column: {column}",
        }
    if column not in frame.columns:
        return {
            "source_id": str(aml_id),
            "column": column,
            "ids": [],
            "status": "missing_column",
        }
    lookup = _lookup_id(aml_id, frame)
    record = lookup.get("record")
    if not record:
        return {
            "source_id": str(aml_id),
            "column": column,
            "ids": [],
            "status": "no_match",
        }
    return {
        "source_id": str(record.get("id", aml_id)),
        "column": column,
        "ids": _parse_relationship(record.get(column)),
        "status": "success",
    }


def _hydrate_relationship(
    aml_id: Any,
    column: str,
    frame: pd.DataFrame,
    fields: list[str] | None = None,
) -> dict[str, Any]:
    linked = _relationship_ids(aml_id, column, frame)
    if linked.get("status") != "success":
        return {**linked, "records": [], "missing_ids": []}
    hydrated = _hydrate_ids(linked["ids"], frame, fields=fields)
    return {**linked, **hydrated}


def _find_references(
    target_id: Any,
    frame: pd.DataFrame,
    columns: list[str] | None = None,
    fields: list[str] | None = None,
) -> dict[str, Any]:
    wanted = _parse_ids(target_id)
    if len(wanted) != 1:
        return {
            "target_id": str(target_id),
            "records": [],
            "status": "invalid_request",
            "message": "find_references expects exactly one AML.ID.",
        }
    target = wanted[0]
    scan_columns = columns or [column for column in RELATIONSHIP_COLUMNS if column in frame.columns]
    invalid_columns = [column for column in scan_columns if column not in RELATIONSHIP_COLUMNS]
    missing_columns = [column for column in scan_columns if column not in frame.columns]
    usable_columns = [
        column
        for column in scan_columns
        if column in RELATIONSHIP_COLUMNS and column in frame.columns
    ]

    mask = pd.Series(False, index=frame.index)
    matched_columns_by_index: dict[Any, list[str]] = {}
    for column in usable_columns:
        contains = frame[column].apply(lambda value: target in _parse_relationship(value))
        mask = mask | contains
        for index in frame.index[contains]:
            matched_columns_by_index.setdefault(index, []).append(column)

    matched = frame.loc[mask].copy()
    output_records = _records(matched, fields=fields)
    for output_record, index in zip(output_records, matched.index, strict=False):
        output_record["matched_relationship_columns"] = matched_columns_by_index.get(index, [])

    return {
        "target_id": target,
        "records": output_records,
        "status": "success",
        "invalid_columns": invalid_columns,
        "missing_columns": missing_columns,
    }


def _dataset_info(frame: pd.DataFrame) -> dict[str, Any]:
    entity_counts: dict[str, int] = {}
    if "entity" in frame.columns:
        entity_counts = {
            str(key): int(value)
            for key, value in frame["entity"].fillna("").astype(str).value_counts().sort_index().items()
        }
    return {
        "rows": int(len(frame)),
        "columns": [str(column) for column in frame.columns],
        "entity_counts": entity_counts,
    }



def _select_records(
    frame: pd.DataFrame,
    entity: str | None = None,
    fields: list[str] | None = None,
    equals: dict[str, Any] | None = None,
    contains: dict[str, Any] | None = None,
    sort_by: str | list[str] | None = None,
    ascending: bool | list[bool] = True,
    limit: int | None = None,
) -> dict[str, Any]:
    """Filter and project ATLAS records using literal, deterministic operations."""
    work = frame.copy()
    invalid_columns: list[str] = []

    if entity is not None:
        if "entity" not in work.columns:
            invalid_columns.append("entity")
        else:
            work = work[
                work["entity"].fillna("").astype(str).str.casefold().eq(str(entity).casefold())
            ].copy()

    for column, value in (equals or {}).items():
        if column not in work.columns:
            invalid_columns.append(str(column))
            continue
        work = work[
            work[column].fillna("").astype(str).str.casefold().eq(str(value).casefold())
        ].copy()

    for column, value in (contains or {}).items():
        if column not in work.columns:
            invalid_columns.append(str(column))
            continue
        work = work[
            work[column].fillna("").astype(str).str.contains(
                str(value), case=False, na=False, regex=False
            )
        ].copy()

    sort_columns: list[str] = []
    if sort_by is not None:
        requested_sort = [sort_by] if isinstance(sort_by, str) else list(sort_by)
        sort_columns = [column for column in requested_sort if column in work.columns]
        invalid_columns.extend(
            str(column) for column in requested_sort if column not in work.columns
        )
        if sort_columns:
            if isinstance(ascending, list):
                directions = list(ascending[: len(sort_columns)])
                if len(directions) < len(sort_columns):
                    directions.extend([True] * (len(sort_columns) - len(directions)))
            else:
                directions = bool(ascending)
            work = work.sort_values(sort_columns, ascending=directions, kind="mergesort")

    total_matches = int(len(work))
    normalized_limit: int | None = None
    if limit is not None:
        try:
            normalized_limit = max(0, int(limit))
        except Exception:
            return {
                "status": "invalid_request",
                "operation": "select",
                "records": [],
                "message": "limit must be an integer or null.",
            }
        work = work.head(normalized_limit).copy()

    missing_fields = [field for field in (fields or []) if field not in work.columns]
    return {
        "status": "success",
        "operation": "select",
        "count": int(len(work)),
        "total_matches": total_matches,
        "records": _records(work, fields=fields),
        "invalid_columns": list(dict.fromkeys(invalid_columns)),
        "missing_fields": missing_fields,
    }

def _rank_by_relationship_count(
    entity: str | None,
    column: str,
    frame: pd.DataFrame,
    limit: int = 10,
    fields: list[str] | None = None,
    include_ties: bool = False,
) -> dict[str, Any]:
    """Rank ATLAS records by the number of IDs in one relationship column."""
    if column not in RELATIONSHIP_COLUMNS:
        return {
            "status": "invalid_column",
            "operation": "rank_by_relationship_count",
            "entity": entity,
            "column": column,
            "records": [],
            "message": f"Unsupported relationship column: {column}",
        }
    if column not in frame.columns:
        return {
            "status": "missing_column",
            "operation": "rank_by_relationship_count",
            "entity": entity,
            "column": column,
            "records": [],
        }

    try:
        normalized_limit = int(limit)
    except Exception:
        normalized_limit = 0
    if normalized_limit < 1:
        return {
            "status": "invalid_request",
            "operation": "rank_by_relationship_count",
            "entity": entity,
            "column": column,
            "records": [],
            "message": "limit must be a positive integer.",
        }

    work = frame.copy()
    if entity is not None:
        if "entity" not in work.columns:
            return {
                "status": "missing_column",
                "operation": "rank_by_relationship_count",
                "entity": entity,
                "column": column,
                "records": [],
                "message": "The dataframe does not contain an 'entity' column.",
            }
        work = work[
            work["entity"].fillna("").astype(str).str.casefold().eq(str(entity).casefold())
        ].copy()

    count_field = f"{column}_count"
    work[count_field] = work[column].apply(lambda value: len(_parse_relationship(value)))

    sort_columns = [count_field]
    ascending = [False]
    if "id" in work.columns:
        sort_columns.append("id")
        ascending.append(True)
    work = work.sort_values(sort_columns, ascending=ascending, kind="mergesort")

    selected = work.head(normalized_limit).copy()
    if include_ties and len(work) > normalized_limit and not selected.empty:
        threshold = int(selected.iloc[-1][count_field])
        selected = work[work[count_field] >= threshold].copy()

    default_fields = [field for field in ["id", "entity", "name", "url"] if field in selected.columns]
    effective_fields = list(fields) if fields is not None else default_fields
    if count_field not in effective_fields:
        effective_fields.append(count_field)

    return {
        "status": "success",
        "operation": "rank_by_relationship_count",
        "entity": entity,
        "column": column,
        "count_field": count_field,
        "limit": normalized_limit,
        "include_ties": bool(include_ties),
        "records": _records(selected, fields=effective_fields),
    }



class _AtlasDatasetAPI:
    """Collision-resistant, operation-first API over one immutable source dataframe copy."""

    def __init__(self, frame: pd.DataFrame) -> None:
        object.__setattr__(self, "_frame", frame)

    def info(self) -> dict[str, Any]:
        return _dataset_info(self._frame)

    def records(
        self,
        frame: Any = None,
        parse_relationships: bool = True,
        fields: list[str] | tuple[str, ...] | None = None,
    ) -> list[dict[str, Any]]:
        return _records(
            self._frame if frame is None else frame,
            parse_relationships=parse_relationships,
            fields=fields,
        )

    def select(
        self,
        entity: str | None = None,
        fields: list[str] | None = None,
        equals: dict[str, Any] | None = None,
        contains: dict[str, Any] | None = None,
        sort_by: str | list[str] | None = None,
        ascending: bool | list[bool] = True,
        limit: int | None = None,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _select_records(
            self._frame if frame is None else frame,
            entity=entity,
            fields=fields,
            equals=equals,
            contains=contains,
            sort_by=sort_by,
            ascending=ascending,
            limit=limit,
        )

    def hydrate(
        self,
        ids: Any,
        fields: list[str] | None = None,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _hydrate_ids(ids, self._frame if frame is None else frame, fields=fields)

    def lookup(
        self,
        aml_id: Any,
        fields: list[str] | None = None,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _lookup_id(aml_id, self._frame if frame is None else frame, fields=fields)

    def relationship_ids(
        self,
        aml_id: Any,
        column: str,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _relationship_ids(aml_id, column, self._frame if frame is None else frame)

    def relationship(
        self,
        aml_id: Any,
        column: str,
        fields: list[str] | None = None,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _hydrate_relationship(
            aml_id,
            column,
            self._frame if frame is None else frame,
            fields=fields,
        )

    def references(
        self,
        target_id: Any,
        columns: list[str] | None = None,
        fields: list[str] | None = None,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _find_references(
            target_id,
            self._frame if frame is None else frame,
            columns=columns,
            fields=fields,
        )

    def rank_relationships(
        self,
        entity: str | None,
        column: str,
        limit: int = 10,
        fields: list[str] | None = None,
        include_ties: bool = False,
        frame: pd.DataFrame | None = None,
    ) -> dict[str, Any]:
        return _rank_by_relationship_count(
            entity,
            column,
            self._frame if frame is None else frame,
            limit=limit,
            fields=fields,
            include_ties=include_ties,
        )

def _safe_builtins() -> dict[str, Any]:
    return {
        "abs": abs,
        "all": all,
        "any": any,
        "bool": bool,
        "dict": dict,
        "enumerate": enumerate,
