def _sandbox_worker(
    connection,
    code: str,
    dataframe: pd.DataFrame,
    max_output_bytes: int,
    memory_limit_mb: int,
) -> None:
    try:
        if memory_limit_mb > 0:
            with contextlib.suppress(Exception):
                import resource

                limit = int(memory_limit_mb) * 1024 * 1024
                resource.setrlimit(resource.RLIMIT_AS, (limit, limit))

        local_df = dataframe.copy(deep=True)

        def records(
            frame: Any = None,
            parse_relationships: bool = True,
            fields: list[str] | tuple[str, ...] | None = None,
        ) -> list[dict[str, Any]]:
            return _records(
                local_df if frame is None else frame,
                parse_relationships=parse_relationships,
                fields=fields,
            )

        def hydrate_ids(
            ids: Any,
            frame: pd.DataFrame | None = None,
            fields: list[str] | None = None,
        ) -> dict[str, Any]:
            return _hydrate_ids(ids, local_df if frame is None else frame, fields=fields)

        def lookup_id(
            aml_id: Any,
            frame: pd.DataFrame | None = None,
            fields: list[str] | None = None,
        ) -> dict[str, Any]:
            return _lookup_id(aml_id, local_df if frame is None else frame, fields=fields)

        def relationship_ids(
            aml_id: Any,
            column: str,
            frame: pd.DataFrame | None = None,
        ) -> dict[str, Any]:
            return _relationship_ids(aml_id, column, local_df if frame is None else frame)

        def hydrate_relationship(
            aml_id: Any,
            column: str,
            frame: pd.DataFrame | None = None,
            fields: list[str] | None = None,
        ) -> dict[str, Any]:
            return _hydrate_relationship(
                aml_id,
                column,
                local_df if frame is None else frame,
                fields=fields,
            )

        def find_references(
            target_id: Any,
            frame: pd.DataFrame | None = None,
            columns: list[str] | None = None,
            fields: list[str] | None = None,
        ) -> dict[str, Any]:
            return _find_references(
                target_id,
                local_df if frame is None else frame,
                columns=columns,
                fields=fields,
            )

        def dataset_info(frame: pd.DataFrame | None = None) -> dict[str, Any]:
            return _dataset_info(local_df if frame is None else frame)

        def rank_by_relationship_count(
            entity: str | None,
            column: str,
            limit: int = 10,
            fields: list[str] | None = None,
            include_ties: bool = False,
            frame: pd.DataFrame | None = None,
        ) -> dict[str, Any]:
            return _rank_by_relationship_count(
                entity,
                column,
                local_df if frame is None else frame,
                limit=limit,
                fields=fields,
                include_ties=include_ties,
            )

        atlas_api = _AtlasDatasetAPI(local_df)

        def select_records(
            entity: str | None = None,
            fields: list[str] | None = None,
            equals: dict[str, Any] | None = None,
            contains: dict[str, Any] | None = None,
            sort_by: str | list[str] | None = None,
            ascending: bool | list[bool] = True,
            limit: int | None = None,
            frame: pd.DataFrame | None = None,
        ) -> dict[str, Any]:
            return _select_records(
                local_df if frame is None else frame,
                entity=entity, fields=fields, equals=equals, contains=contains,
                sort_by=sort_by, ascending=ascending, limit=limit,
            )

        sentinel = object()
        globals_: dict[str, Any] = {
            "__builtins__": _safe_builtins(),
            "atlas": atlas_api,
            "df": local_df,
            "pd": pd,
            "pandas": pd,
            "json": json,
            "ast": ast,
            "math": math,
            "re": re,
            "RELATIONSHIP_COLUMNS": list(RELATIONSHIP_COLUMNS),
            "parse_relationship": _parse_relationship,
            "parse_ids": _parse_ids,
            "json_ready": _json_ready,
            "records": records,
            "hydrate_ids": hydrate_ids,
            "lookup_id": lookup_id,
            "relationship_ids": relationship_ids,
            "hydrate_relationship": hydrate_relationship,
            "find_references": find_references,
            "dataset_info": dataset_info,
            "rank_by_relationship_count": rank_by_relationship_count,
            "select_records": select_records,
            "result": sentinel,
        }

        stdout = io.StringIO()
        with contextlib.redirect_stdout(stdout):
            exec(compile(code, "<atlas-python-sandbox>", "exec"), globals_, globals_)

        result = globals_.get("result", sentinel)
        if result is sentinel:
            raise ValueError("Code must assign its final JSON-compatible value to `result`.")

        normalized = _json_ready(result)
        encoded = json.dumps(normalized, ensure_ascii=False, allow_nan=False)
        output_size = len(encoded.encode("utf-8"))
        if output_size > max_output_bytes:
            connection.send(
                {
                    "ok": False,
                    "error_code": "output_too_large",
                    "error": (
                        f"Result is {output_size} bytes, exceeding the configured "
                        f"{max_output_bytes}-byte limit. Return fewer rows or fields."
                    ),
                }
            )
            return

        connection.send(
            {
                "ok": True,
                "result": normalized,
                "output_bytes": output_size,
                "stdout_bytes": len(stdout.getvalue().encode("utf-8")),
            }
        )
    except Exception as exc:
        connection.send(
            {
                "ok": False,
                "error_code": "execution_error",
                "error": f"{type(exc).__name__}: {exc!s}",
                "traceback": traceback.format_exc(limit=8),
            }
        )
    finally:
        with contextlib.suppress(Exception):
            connection.close()


