            name="memory_limit_mb",
            display_name="Worker Memory Limit (MB)",
            info=(
                "Optional address-space limit for the worker process. Use 0 to disable. "
                "Set only after testing with the deployed dataset."
            ),
            value=0,
            advanced=True,
        ),
        CodeInput(
            name="python_code",
            display_name="Python Code",
            info=(
                "Use the preloaded `atlas` API for common operations and `df`/`pd` only for advanced analysis. "
                "Ordinary local variable names are allowed, including names such as `records`. "
                "Assign the final native JSON-compatible value to `result`, or make it the final expression. "
                "Do not print or JSON-encode results. Imports and external I/O remain restricted."
            ),
            value=(
                "# Common operations use the collision-resistant atlas API.\n"
                "result = atlas.info()"
            ),
            input_types=["Message"],
            tool_mode=True,
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Results",
            name="results",
            method="atlas_dataset_sandbox",
            types=["json"],
        ),
    ]

    def _coerce_text(self, value: Any) -> str:
        if value is None:
            return ""
        if isinstance(value, str):
            return value
        if hasattr(value, "text") and isinstance(value.text, str):
            return value.text
        if hasattr(value, "data") and isinstance(value.data, dict):
            for key in ("text", "code", "python_code"):
                if value.data.get(key):
                    return str(value.data[key])
        return str(value)

    def _get_csv_path(self) -> str:
        value = getattr(self, "csv_file", None)
        if value is None:
            raise ValueError("No CSV file was configured.")
        if isinstance(value, list):
            if not value:
                raise ValueError("CSV file input was an empty list.")
            value = value[0]
        if isinstance(value, str):
            return value
        if hasattr(value, "text") and isinstance(value.text, str):
            return value.text
        if hasattr(value, "path"):
            return str(value.path)
        if hasattr(value, "data") and isinstance(value.data, dict):
            for key in ("path", "file_path", "csv_file", "source"):
                if value.data.get(key):
                    return str(value.data[key])
        return str(value)

    def _parse_read_csv_kwargs(self) -> dict[str, Any]:
        raw = getattr(self, "read_csv_kwargs", "{}")
        if isinstance(raw, dict):
            return raw
        text = self._coerce_text(raw).strip()
        if not text:
            return {}
        try:
            parsed = json.loads(text)
        except Exception:
            try:
                parsed = ast.literal_eval(text)
            except Exception as exc:
                raise ValueError(
                    f"read_csv_kwargs must be a JSON object or Python dict string: {exc!s}"
                ) from exc
        if not isinstance(parsed, dict):
            raise ValueError("read_csv_kwargs must parse to a dictionary.")
        return parsed

    def _dataframe_cache_key(self) -> tuple[Any, ...]:
        csv_path = self._get_csv_path()
        kwargs = self._parse_read_csv_kwargs()
        fingerprint: Any = csv_path
        with contextlib.suppress(Exception):
            path = Path(csv_path)
            if path.exists():
                stat = path.stat()
                fingerprint = (str(path.resolve()), stat.st_mtime_ns, stat.st_size)
        return (fingerprint, json.dumps(kwargs, sort_keys=True, default=str))

    def _get_dataframe(self) -> pd.DataFrame:
        key = self._dataframe_cache_key()
        if getattr(self, "_dataframe_key", None) != key:
            csv_path = self._get_csv_path()
            kwargs = self._parse_read_csv_kwargs()
            try:
                loaded = pd.read_csv(csv_path, **kwargs)
            except Exception as exc:
                raise ValueError(f"Failed to load the configured CSV: {exc!s}") from exc
            self._dataframe_original = loaded.copy(deep=True)
            self._dataframe_key = key
            self.log(
                f"Loaded ATLAS dataframe with {len(loaded)} rows and {len(loaded.columns)} columns."
            )
        return self._dataframe_original

    def _prepare_code(self, code: str) -> tuple[str, list[str]]:
        if not code.strip():
            raise SandboxValidationError("Python code is empty.")
        max_code_chars = max(1, int(getattr(self, "max_code_chars", 16000)))
        if len(code) > max_code_chars:
            raise SandboxValidationError(
                f"Python code exceeds the configured {max_code_chars}-character limit."
            )
        try:
            tree = ast.parse(code, mode="exec")
        except SyntaxError as exc:
            raise SandboxValidationError(f"Syntax error: {exc!s}") from exc

        import_stripper = _RedundantImportStripper()
        tree = import_stripper.visit(tree)
        tree = _ResultCaptureTransformer().visit(tree)
        ast.fix_missing_locations(tree)
        _SandboxValidator().visit(tree)

        prepared_code = ast.unparse(tree)
        return prepared_code, import_stripper.removed_imports

    def _dataframe_metadata(self, frame: pd.DataFrame) -> dict[str, Any]:
        return {
            "rows": int(len(frame)),
            "columns": [str(column) for column in frame.columns],
        }

    def _error(
        self,
        code: str,
        message: str,
        frame: pd.DataFrame | None = None,
    ) -> JSON:
        data: dict[str, Any] = {
            "status": "error",
            "error": {"code": code, "message": message},
        }
        if frame is not None:
            data["dataframe"] = self._dataframe_metadata(frame)
        return JSON(data=data)

    def atlas_dataset_sandbox(self) -> JSON:
        """Langflow tool action for exact ATLAS dataset analysis."""
        return self.run_python_repl()

    def run_python_repl(self) -> JSON:
        frame: pd.DataFrame | None = None
        try:
            frame = self._get_dataframe()
            submitted_code = self._coerce_text(getattr(self, "python_code", None))
            code, ignored_imports = self._prepare_code(submitted_code)

            timeout_seconds = min(60, max(1, int(getattr(self, "timeout_seconds", 15))))
            max_output_bytes = max(1024, int(getattr(self, "max_output_bytes", 300000)))
            memory_limit_mb = max(0, int(getattr(self, "memory_limit_mb", 0)))

            try:
                context = multiprocessing.get_context("fork")
            except ValueError:
                return self._error(
                    "unsupported_platform",
                    "ATLAS Dataset Sandbox requires a POSIX runtime with fork support.",
                    frame,
                )

            receive_connection, send_connection = context.Pipe(duplex=False)
            process = context.Process(
                target=_sandbox_worker,
                args=(send_connection, code, frame, max_output_bytes, memory_limit_mb),
                daemon=True,
            )
            process.start()
            send_connection.close()

            payload: dict[str, Any] | None = None
            if receive_connection.poll(timeout_seconds):
                payload = receive_connection.recv()
            else:
                process.terminate()
                process.join(timeout=2)
                return self._error(
                    "timeout",
                    f"Python execution exceeded the {timeout_seconds}-second limit.",
                    frame,
                )

            process.join(timeout=2)
            if process.is_alive():
                process.terminate()
                process.join(timeout=2)
            receive_connection.close()

            if not payload:
                return self._error(
                    "worker_failed",
                    "Python worker exited without returning a result.",
                    frame,
                )

            if not payload.get("ok"):
                trace = payload.pop("traceback", None)
                if trace:
                    self.log(f"ATLAS Dataset Sandbox worker error:\n{trace}")
                return self._error(
                    str(payload.get("error_code", "execution_error")),
                    str(payload.get("error", "Python execution failed.")),
                    frame,
                )

            response: dict[str, Any] = {
                "status": "success",
                "result": payload.get("result"),
                "dataframe": self._dataframe_metadata(frame),
                "execution": {
                    "output_bytes": int(payload.get("output_bytes", 0)),
                },
            }
            warnings: list[str] = []
            if ignored_imports:
                warnings.append(
                    "Ignored redundant imports for preloaded modules: "
                    + "; ".join(ignored_imports)
                    + "."
                )
            if int(payload.get("stdout_bytes", 0)) > 0:
                warnings.append(
                    "Printed stdout was ignored. Use the native value assigned to `result`."
                )
            if warnings:
                response["warnings"] = warnings
            return JSON(data=response)

        except SandboxValidationError as exc:
            self.log(f"ATLAS Dataset Sandbox rejected code: {exc!s}")
            return self._error("unsafe_or_invalid_code", str(exc), frame)
        except ValueError as exc:
            self.log(f"ATLAS Dataset Sandbox configuration error: {exc!s}")
            return self._error("invalid_configuration", str(exc), frame)
        except Exception as exc:
            self.log(f"ATLAS Dataset Sandbox failed: {type(exc).__name__}: {exc!s}")
            return self._error(
                "sandbox_failed",
                "ATLAS Dataset Sandbox failed unexpectedly. Check the component configuration and logs.",
                frame,
            )

    def build(self):
        return self.run_python_repl()

import html
import json
import re
import urllib.parse
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, IntInput, Output, StrInput
from lfx.schema.data import JSON


class KumuSubgraphURL(Component):
    """Generate a validated, focused Kumu embed URL from verified ATLAS IDs."""

    display_name = "ATLAS Graph Generator"
    description = (
        "Generate a focused Kumu URL and iframe from verified ATLAS IDs. "
        "Validates syntax, removes exact duplicates, preserves order, and performs no discovery."
    )
    documentation: str = "https://docs.langflow.org/components-custom-components"
    icon = "link"
    name = "KumuSubgraphURL"

    inputs = [
        DataInput(
            name="ids",
            display_name="Verified ATLAS IDs",
            info=(
                "JSON object containing an ordered `ids` list. Example: "
                '{"ids": ["AML.T0015", "AML.M0003"]}. The first ID is the anchor.'
            ),
            tool_mode=True,
            required=True,
        ),
        StrInput(
            name="project_id",
            display_name="Project ID",
            required=True,
        ),
        StrInput(
            name="map_name",
            display_name="Map",
            value="atlas",
            required=True,
            info="Configured Kumu map view name.",
        ),
        IntInput(
            name="max_focus_ids",
            display_name="Maximum Focus IDs",
            info="Administrative cap that prevents oversized and overly broad focus URLs.",
            value=50,
            advanced=True,
        ),
        IntInput(
            name="max_url_length",
            display_name="Maximum URL Length",
            info="Reject generated URLs longer than this many characters.",
            value=8000,
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            name="results",
            display_name="Results",
            method="atlas_graph_generator",
            types=["json"],
        )
    ]

    ID_PATTERN = re.compile(r"^AML\.(?:TA\d{4}|T\d{4}(?:\.\d{3})?|M\d{4}|CS\d{4})$")
    PROJECT_PATTERN = re.compile(r"^[A-Za-z0-9_-]+$")

    def _coerce_payload(self, value: Any) -> Any:
        if value is None:
            return None
        if isinstance(value, (dict, list, tuple, set, str)):
            return value
        data = getattr(value, "data", None)
        if isinstance(data, (dict, list, str)):
            return data
        text = getattr(value, "text", None)
        if isinstance(text, str):
            return text
        return value

    def _extract_values(self, value: Any) -> list[Any]:
        value = self._coerce_payload(value)
        if value is None:
            return []
        if isinstance(value, dict):
            return self._extract_values(value.get("ids"))
        if isinstance(value, (list, tuple, set)):
            return list(value)
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return []
            try:
                parsed = json.loads(text)
            except json.JSONDecodeError:
                return [part.strip() for part in re.split(r"[,\n]", text) if part.strip()]
            return self._extract_values(parsed)
        raise ValueError("ATLAS Graph Generator input must be an object containing an `ids` list.")

    def _validate_ids(self, value: Any) -> tuple[list[str], list[str], list[str]]:
        raw_values = self._extract_values(value)
        valid: list[str] = []
        invalid: list[str] = []
        duplicates: list[str] = []
        seen: set[str] = set()

        for raw_value in raw_values:
            candidate = str(raw_value).strip()
            if not candidate:
                continue
            if not self.ID_PATTERN.fullmatch(candidate):
                invalid.append(candidate)
                continue
            if candidate in seen:
                if candidate not in duplicates:
                    duplicates.append(candidate)
                continue
            seen.add(candidate)
            valid.append(candidate)

        return valid, invalid, duplicates

    def _kumu_identifier(self, aml_id: str) -> str:
        return aml_id.lower().replace(".", "-")

    def _build_iframe(self, url: str) -> str:
        escaped_url = html.escape(url, quote=True)
        return (
            f'<iframe src="{escaped_url}" width="600" height="400" frameborder="0" '
            'loading="lazy" referrerpolicy="no-referrer" '
            'title="MITRE ATLAS focused graph"></iframe>'
        )

    def _error(
        self,
        code: str,
        message: str,
        *,
        ids: list[str] | None = None,
        invalid_ids: list[str] | None = None,
        duplicates_removed: list[str] | None = None,
    ) -> JSON:
        return JSON(
            data={
                "status": "error",
                "ids": ids or [],
                "invalid_ids": invalid_ids or [],
                "duplicates_removed": duplicates_removed or [],
                "url": "",
                "iframe": "",
                "error": {"code": code, "message": message},
            }
        )

    def atlas_graph_generator(self) -> JSON:
        """Langflow tool action for focused Kumu graph generation."""
        return self.build_url()

    def build_url(self) -> JSON:
        try:
            ids, invalid_ids, duplicates = self._validate_ids(getattr(self, "ids", None))

            if invalid_ids:
                return self._error(
                    "invalid_ids",
                    "One or more values are not valid canonical ATLAS IDs. No graph was generated.",
                    ids=ids,
                    invalid_ids=invalid_ids,
                    duplicates_removed=duplicates,
                )
            if not ids:
                return self._error(
                    "no_ids",
                    "Provide at least one verified ATLAS ID.",
                    duplicates_removed=duplicates,
                )

            max_focus_ids = max(1, int(getattr(self, "max_focus_ids", 50)))
            if len(ids) > max_focus_ids:
                return self._error(
                    "too_many_ids",
                    f"Received {len(ids)} focus IDs; the configured limit is {max_focus_ids}.",
                    ids=ids,
                    duplicates_removed=duplicates,
                )

            project_id = str(getattr(self, "project_id", "") or "").strip()
            if not project_id or not self.PROJECT_PATTERN.fullmatch(project_id):
                return self._error(
                    "invalid_project_id",
                    "The configured Kumu project ID is empty or contains unsupported characters.",
                    ids=ids,
                    duplicates_removed=duplicates,
                )

            map_name = str(getattr(self, "map_name", "") or "").strip().lower()
            if not map_name:
                return self._error(
                    "invalid_map_name",
                    "The configured Kumu map name is empty.",
                    ids=ids,
                    duplicates_removed=duplicates,
                )

            encoded_project = urllib.parse.quote(project_id, safe="-_")
            encoded_map = urllib.parse.quote(map_name, safe="-_.~")
            anchor = self._kumu_identifier(ids[0])
            encoded_anchor = urllib.parse.quote(anchor, safe="-_")

            if len(ids) == 1:
                focus_value = "1"
                focus_mode = "single_anchor"
            else:
                directives = [f"#{self._kumu_identifier(aml_id)} out 1" for aml_id in ids]
                focus_value = urllib.parse.quote(", ".join(directives), safe="")
                focus_mode = "multi_anchor_outbound_one_hop"

            url = (
                f"https://embed.kumu.io/{encoded_project}"
                f"#{encoded_map}/{encoded_anchor}"
                f"?focus={focus_value}"
            )

            max_url_length = max(256, int(getattr(self, "max_url_length", 8000)))
            if len(url) > max_url_length:
                return self._error(
                    "url_too_long",
                    f"Generated URL length {len(url)} exceeds the configured limit {max_url_length}.",
                    ids=ids,
                    duplicates_removed=duplicates,
                )

            return JSON(
                data={
                    "status": "success",
                    "ids": ids,
                    "anchor": ids[0],
                    "focus_mode": focus_mode,
                    "duplicates_removed": duplicates,
                    "invalid_ids": [],
                    "url": url,
                    "iframe": self._build_iframe(url),
                }
            )

        except ValueError as exc:
            self.log(f"ATLAS Graph Generator validation error: {exc!s}")
            return self._error("invalid_input", str(exc))
        except Exception as exc:
            self.log(f"ATLAS Graph Generator failed: {type(exc).__name__}: {exc!s}")
            return self._error(
                "generation_failed",
                "The Kumu URL could not be generated. Check the component configuration and logs.",
            )
